private long calculatePositiveDifferenceSum(int[] A) {
    long totalSum = 0;
    int N = A.length;
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            int difference = A[j] - A[i];
            if (difference > 0) {
                totalSum += difference;
            }
        }
    }
    return totalSum;
}
